import torch
E=W('model.embed_tokens.weight')
cats={'code':" def return import self print elif lambda yield async await None True False class __init__ range len append dict str int float try except raise".split(),
'french':" le la les des une est pour avec dans sont nous vous mais plus très aussi être avoir fait comme".split(),
'digit':list("0123456789"),
'german':" der die das und ist nicht mit sich auch wird werden haben eine einen dem".split(),
'english':" the and of to in that is was for with as on by at from this have but not are".split()}
def ids(ws):
    out=[]
    for w in ws:
        for v in [w,' '+w]:
            t=encode(v)
            if len(t)==1: out.append(t[0])
    return sorted(set(out))
I={c:ids(w) for c,w in cats.items()}
for L in [2,3,4,5,6]:
    G=W(f'model.layers.{L}.feed_forward.gate.weight'); n=W(f'model.layers.{L}.ffn_norm.weight')
    X=E*n
    P={}
    for c,i in I.items():
        top=(X[i]@G.T).topk(4,dim=1).indices
        f=torch.zeros(64)
        for r in top: f[r]+=1
        P[c]=f/len(i)
    for c in ['code','french','german','digit']:
        oth=torch.stack([P[d] for d in P if d!=c]).max(0).values
        sel=P[c]-oth; t=sel.argsort(descending=True)[:8]
        print(L,c,[(int(k),round(float(P[c][k]),2),round(float(sel[k]),2)) for k in t])
